Import PMES.

Section InObjS.
Context {SCFG_P : ScfgP}.
Variable L : asan_layout.
Variable ar : asan_run.
Variable C : asan_statics_cells.
Variable HI : asan_iface.
Hypothesis HIok : PmHeapIfaceA.asan_iface_ok L ar C SCFG HI.
Hypothesis LAY : L5A.as0_layout L C.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps (hl_segs L) (@mkst fx R (Z_to_bv 64 pc) M (seg_rom (hl_segs L))) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom (hl_segs L))) -> PMSA.fp_ok fx -> PMSA.fp_ok fx'.
Variable CL : Z.
Abbreviation IC := PMLA.C_xboth.
Abbreviation EC := PMESA.EC_xboth.
Abbreviation RSEGS := (hl_segs L).
Variable onmax : Z.
Variable IL0 : icpt_layout.
Hypothesis ACC_OPEN : PMESA.img_aacc HI EVBB.OPEN_TXT 1.                                                    (* [comment removed for export] *)
Hypothesis ISH : rt_img_shadow L IL0 HI.                                                                  (* [comment removed for export] *)
Hypothesis POI_VBO : Forall (fun r : Z * Z => EVBB.VBO + 8 <= fst r \/ snd r <= EVBB.VBO) (icl_poison IL0).
Hypothesis FOOTXC : forall a, PMLA.in_footx PMLA.C_xboth a -> ~ hl_rt_static L a /\ ~ hl_rt_ro L a.         (* [comment removed for export] *)
Hypothesis APPEND_OK : PMESA.str_append_x_specA L ar HI IC CL EVBB.PC_APPEND.                              (* [comment removed for export] *)
Hypothesis CLOK : EKA.clok CL onmax.                                                                       (* [comment removed for export] *)
Hypothesis PUSH_SLOW_OK : PMES2A.push_slow_specXB L ar HI onmax EVBB.PC_PUSH.                               (* [comment removed for export] *)

